import{d,C as p,o as c,c as a,j as n,a as s,E as r,a3 as l}from"./chunks/framework.Q4yG9rk_.js";const f=JSON.parse('{"title":"荀子·第27篇·大略","description":"《荀子·大略》——汇集礼义、为学与处世的短章杂论。","frontmatter":{"title":"荀子·第27篇·大略","description":"《荀子·大略》——汇集礼义、为学与处世的短章杂论。","category":"guide","aliases":["荀子大略","荀子第27篇"],"source":["维基文库《荀子/大略篇》，修订号 1392643"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/xunzi/chapter-27.md","filePath":"lizhimingde/xunzi/chapter-27.md","lastUpdated":1794362429000}'),o={name:"lizhimingde/xunzi/chapter-27.md"},x=d({...o,setup(h){const i=[{id:"p001",sentences:[["君人者，隆礼尊贤而王，重法爱民而霸，好利多诈而危。欲近四旁，莫如中央，故王者必居天下之中，礼也。"]]},{id:"p002",sentences:[["天子外屏，诸侯内屏，礼也。外屏、不欲见外也；内屏、不欲见内也。"]]},{id:"p003",sentences:[["诸侯召其臣，臣不俟驾，颠倒衣裳而走，礼也。诗曰：“颠之倒之，自公召之。”天子召诸侯，诸侯辇舆就马，礼也。诗曰：“我出我舆，于彼牧矣。自天子所，谓我来矣。”"]]},{id:"p004",sentences:[["天子山冕，诸侯玄冠，大夫裨冕，士韦弁，礼也。"]]},{id:"p005",sentences:[["天子御珽，诸侯御荼，大夫服笏，礼也。"]]},{id:"p006",sentences:[["天子雕弓，诸侯彤弓，大夫黑弓，礼也。"]]},{id:"p007",sentences:[["诸侯相见，卿为介，以其教士毕行，使仁居守。"]]},{id:"p008",sentences:[["聘人以珪，问士以璧，召人以瑗，绝人以玦，反绝以环。"]]},{id:"p009",sentences:[["人主仁心设焉，知其役也，礼其尽也，故王者先仁而后礼，天施然也。"]]},{id:"p010",sentences:[["聘礼志曰：“币厚则伤德，财侈则殄礼。”礼云礼云，玉帛云乎哉！诗曰：“物其指矣，唯其偕矣。”不时宜，不敬文，不驩欣，虽指非礼也。"]]},{id:"p011",sentences:[["水行者表深，使人无陷；治民者表乱，使人无失，礼者，其表也。先王以礼义表天下之乱；今废礼者，是弃表也，故民迷惑而陷祸患，此刑罚之所以繁也。"]]},{id:"p012",sentences:[["舜曰：“维予从欲而治。”故礼之生，为贤人以下至庶民也，非为成圣也；然而亦所以成圣也，不学不成；尧学于君畴，舜学于务成昭，禹学于西王国。"]]},{id:"p013",sentences:[["五十不成丧，七十唯衰存。"]]},{id:"p014",sentences:[["亲迎之礼，父南向而立，子北面而跪，醮而命之：“往迎尔相，成我宗事，隆率以敬先妣之嗣，若则有常。”子曰：“诺！唯恐不能，敢忘命矣！”"]]},{id:"p015",sentences:[["夫行也者，行礼之谓也。礼也者，贵者敬焉，老者孝焉，长者弟焉，幼者慈焉，贱者惠焉。"]]},{id:"p016",sentences:[["赐予其宫室，犹用庆赏于国家也；忿怒其臣妾，犹用刑罚于万民也。"]]},{id:"p017",sentences:[["君子之于子，爱之而勿面，使之而勿视，道之以道而勿彊。"]]},{id:"p018",sentences:[["礼以顺人心为本，故亡于礼经而顺于人心者，皆礼也。"]]},{id:"p019",sentences:[["礼之大凡：－－事生、饰驩也，送死、饰哀也，军旅、施威也。"]]},{id:"p020",sentences:[["亲亲、故故、庸庸、劳劳，仁之杀也；贵贵、尊尊、贤贤、老老、长长、义之伦也。行之得其节，礼之序也。仁、爱也，故亲；义、理也，故行；礼、节也，故成。仁有里，义有门；仁、非其里而处之，非仁也；义，非其门而由之，非义也。推恩而不理，不成仁；遂理而不敢，不成义；审节而不和，不成礼；和而不发，不成乐。故曰：仁义礼乐，其致一也。君子处仁以义，然后仁也；行义以礼，然后义也；制礼反本成末，然后礼也。三者皆通，然后道也。"]]},{id:"p021",sentences:[["货财曰赙，舆马曰赗，衣服曰襚，玩好曰赠，玉贝曰唅。赙赗、所以佐生也，赠襚、所以送死也。送死不及柩尸，吊生不及悲哀，非礼也。故吉行五十，奔丧百里，赗赠及事，礼之大也。"]]},{id:"p022",sentences:[["礼者、政之挽也；为政不以礼，政不行矣。"]]},{id:"p023",sentences:[["天子即位，上卿进曰：“如之何忧之长也？能除患则为福，不能除患则为贼。”授天子一策。中卿进曰：“配天而有下土者，先事虑事，先患虑患。先事虑事谓之接，接则事优成。先患虑患谓之豫，豫则祸不生。事至而后虑者谓之后，后则事不举。患至而后虑者谓之困，困则祸不可御。”授天子二策。下卿进曰：“敬戒无怠，庆者在堂，吊者在闾。祸与福邻，莫知其门。豫哉！豫哉！万民望之。”授天子三策。"]]},{id:"p024",sentences:[["禹见耕者耦、立而式，过十室之邑、必下。"]]},{id:"p025",sentences:[["杀大蚤，朝大晚，非礼也。治民不以礼，动斯陷矣。"]]},{id:"p026",sentences:[["平衡曰拜，下衡曰稽首，至地曰稽颡。"]]},{id:"p027",sentences:[["大夫之臣，拜不稽首，非尊家臣也，所以辟君也。"]]},{id:"p028",sentences:[["一命齿于乡，再命齿于族，三命，族人虽七十不敢先。上大夫，中大夫，下大夫。"]]},{id:"p029",sentences:[["吉事尚尊，丧事尚亲。"]]},{id:"p030",sentences:[["聘、问也。享、献也。私觌、私见也。"]]},{id:"p031",sentences:[["言语之美，穆穆皇皇。朝廷之美，济济枪枪。"]]},{id:"p032",sentences:[["为人臣下者，有谏而无讪，有亡而无疾，有怨而无怒。"]]},{id:"p033",sentences:[["君于大夫，三问其疾，三临其丧；于士，一问，一临。诸侯非问疾吊丧不之臣之家。"]]},{id:"p034",sentences:[["既葬，君若父之友食之则食矣，不辟梁肉，有醴酒则辞。"]]},{id:"p035",sentences:[["寝不逾庙，䜩衣不逾祭服，礼也。"]]},{id:"p036",sentences:[["汤之咸，见夫妇。夫妇之道，不可不正也，君臣父子之本也。咸、感也，以高下下，以男下女，柔上而刚下。"]]},{id:"p037",sentences:[["聘士之义，亲迎之道，重始也。"]]},{id:"p038",sentences:[["礼者，人之所履也，失所履，必颠蹶陷溺。所失微而其为乱大者，礼也。"]]},{id:"p039",sentences:[["礼之于正国家也，如权衡之于轻重也，如绳墨之于曲直也。故人无礼不生，事无礼不成，国家无礼不宁。君臣不得不尊，父子不得不亲，兄弟不得不顺，夫妇不得不驩，少者以长，老者以养。故天地生之，圣人成之。"]]},{id:"p040",sentences:[["和鸾之声，步中武象，趋中韶护。君子听律习容而后出。"]]},{id:"p041",sentences:[["霜降逆女，冰泮杀止，十日一御。"]]},{id:"p042",sentences:[["坐视膝，立视足，应对言语视面。立视前六尺而大之－－六六三十六，三丈六尺。"]]},{id:"p043",sentences:[["文貌情用，相为内外表里。礼之中焉，能思索谓之能虑。"]]},{id:"p044",sentences:[["礼者，本末相顺，终始相应。"]]},{id:"p045",sentences:[["礼者，以财物为用，以贵贱为文，以多少为异。"]]},{id:"p046",sentences:[["下臣事君以货，中臣事君以身，上臣事君以人。"]]},{id:"p047",sentences:[["易曰：“复自道，何其咎？”春秋贤穆公，以为能变也。"]]},{id:"p048",sentences:[["士有妒友，则贤交不亲；君有妒臣，则贤人不至。蔽公者谓之昧，隐贤者谓之妒，奉妒昧者谓之交谲。交谲之人，妒昧之臣，国之薉孽也。"]]},{id:"p049",sentences:[["口能言之，身能行之，国宝也。口不能言，身能行之，国器也。口能言之，身不能行，国用也。口言善，身行恶，国妖也。治国者敬其宝，爱其器，任其用，除其妖。"]]},{id:"p050",sentences:[["不富无以养民情，不教无以理民性。故家五亩宅，百亩田，务其业，而勿夺其时，所以富之也。立大学，设庠序，修六礼，明七教，所以道之也。诗曰：“饮之食之，教之诲之。”王事具矣。"]]},{id:"p051",sentences:[["武王始入殷，表商容之闾，释箕子之囚，哭比干之墓，天下乡善矣。"]]},{id:"p052",sentences:[["天下国有俊士，世有贤人。迷者不问路，溺者不问遂，亡人好独。诗曰：“我言维服，勿用为笑。先民有言，询于刍荛。”言博问也。"]]},{id:"p053",sentences:[["有法者以法行，无法者以类举。以其本知其末，以其左知其右，凡百事异理而相守也。庆赏刑罚，通类而后应；政教习俗，相顺而后行。"]]},{id:"p054",sentences:[["八十者一子不事，九十者举家不事，废疾非人不养者，一人不事，父母之丧，三年不事，齐衰大功，三月不事，从诸侯来，与新有昏，期不事。"]]},{id:"p055",sentences:[["子谓子家驹续然大夫，不如晏子；晏子功用之臣也，不如子产；子产惠人也，不如管仲；管仲之为人，力功不力义，力知不力仁，野人也，不可为天子大夫。"]]},{id:"p056",sentences:[["孟子三见宣王，不言事。门人曰：“曷为三遇齐王而不言事？”孟子曰：“吾先攻其邪心。”"]]},{id:"p057",sentences:[["公行子之之燕，遇曾元于涂，曰：“燕君何如？”曾元曰：“志卑。志卑者轻物，轻物者不求助；苟不求助，何能举？氐羌之虏也，不忧其系垒也，而忧其不焚也。利夫秋毫，害靡国家，然且为之，几为知计哉！”"]]},{id:"p058",sentences:[["今夫亡箴者，终日求之而不得；其得之也，非目益明也，眸而见之也。心之于虑亦然。"]]},{id:"p059",sentences:[["“义”与“利”者，人之所两有也。虽尧舜不能去民之欲利；然而能使其欲利不克其好义也。虽桀纣不能去民之好义；然而能使其好义不胜其欲利也。故义胜利者为治世，利克义者为乱世。上重义则义克利，上重利则利克义。故天子不言多少，诸侯不言利害，大夫不言得丧，士不通货财。有国之君不息牛羊，错质之臣不息鸡豚，冢卿不修币，大夫不为场园，从士以上皆羞利而不与民争业，乐分施而耻积藏；然故民不困财，贫窭者有所窜其手。"]]},{id:"p060",sentences:[["文王诛四，武王诛二，周公卒业，至成康则案无诛已。"]]},{id:"p061",sentences:[["多积财而羞无有，重民任而诛不能，此邪行之所以起，刑罚之所以多也。"]]},{id:"p062",sentences:[["上好义，则民暗饰矣！上好富，则民死利矣！二者治乱之衢也。民语曰：“欲富乎？忍耻矣！倾绝矣！绝故旧矣！与义分背矣！”上好富，则人民之行如此，安得不乱！"]]},{id:"p063",sentences:[["汤旱而祷曰：“政不节与？使民疾与？何以不雨至斯极也！宫室荣与？妇谒盛与？何以不雨至斯之极也！苞苴行与？谗夫兴与？何以不雨至斯极也！”"]]},{id:"p064",sentences:[["天之生民，非为君也；天之立君，以为民也。故古者，列地建国，非以贵诸侯而已；列官职，差爵禄，非以尊大夫而已。"]]},{id:"p065",sentences:[["主道知人，臣道知事。故舜之治天下，不以事诏而万物成。农精于田，而不可以为田师，工贾亦然。"]]},{id:"p066",sentences:[["以贤易不肖，不待卜而后知吉。以治伐乱，不待战而后知克。"]]},{id:"p067",sentences:[["齐人欲伐鲁，忌卞庄子，不敢过卞。晋人欲伐卫，畏子路，不敢过蒲。"]]},{id:"p068",sentences:[["不知而问尧舜，无有而求天府。－－曰：先王之道，则尧舜已；六贰之博，则天府已。"]]},{id:"p069",sentences:[["君子之学如蜕，幡然迁之。故其行效，其立效，其置颜色、出辞气效。无留善，无宿问。"]]},{id:"p070",sentences:[["善学者尽其理，善行者究其难。"]]},{id:"p071",sentences:[["君子立志如穷，虽天子三公问正，以是非对。"]]},{id:"p072",sentences:[["君子隘穷而不失，劳倦而不苟，临患难而不忘细席之言。岁不寒无以知松柏，事不难无以知君子无日不在是。"]]},{id:"p073",sentences:[["雨小，汉故潜。夫尽小者大，积微者箸，德至者色泽洽，行尽而声问远，小人不诚于内而求之于外。"]]},{id:"p074",sentences:[["言而不称师谓之畔，教而不称师谓之倍。倍畔之人，明君不内，朝士大夫遇诸涂不与言。"]]},{id:"p075",sentences:[["不足于行者，说过；不足于信者，诚言。故春秋善胥命，而诗非屡盟，其心一也。善为诗者不说，善为易者不占，善为礼者不相，其心同也。"]]},{id:"p076",sentences:[["曾子曰：“孝子言为可闻，行为可见。言为可闻，所以说远也；行为可见，所以说近也；近者说则亲，远者悦则附；亲近而附远，孝子之道也。”"]]},{id:"p077",sentences:[["曾子行，晏子从于郊，曰：“婴闻之：君子赠人以言，庶人赠人以财。婴贫无财，请假于君子，赠吾子以言：乘舆之轮，太山之木也，示诸檃栝，三月五月，为帱采，敝而不反其常。君子之檃栝，不可不谨也。慎之！兰茞槁本，渐于蜜醴，一佩易之。正君渐于香酒，可谗而得也。君子之所渐，不可不慎也。”"]]},{id:"p078",sentences:[["人之于文学也，犹玉之于琢磨也。诗曰：“如切如磋，如琢如磨。”谓学问也。和之璧，井里之厥也，玉人琢之，为天子宝。子赣季路故鄙人也，被文学，服礼义，为天下列士。"]]},{id:"p079",sentences:[["学问不厌，好士不倦，是天府也。"]]},{id:"p080",sentences:[["君子疑则不言，未问则不言，道远日益矣。"]]},{id:"p081",sentences:[["多知而无亲，博学而无方，好多而无定者，君子不与。"]]},{id:"p082",sentences:[["少不讽诵，壮不论议，虽可，未成也。"]]},{id:"p083",sentences:[["君子壹教，弟子壹学，亟成。"]]},{id:"p084",sentences:[["君子进则益上之誉，而损下之忧。不能而居之，诬也；无益而厚受之，窃也。学者非必为仕，而仕者必如学。"]]},{id:"p085",sentences:[["子贡问于孔子曰：“赐倦于学矣，愿息事君。”孔子曰：“诗云：‘温恭朝夕，执事有恪。’事君难，事君焉可息哉！”“然则，赐愿息事亲。”孔子曰：“诗云：‘孝子不匮，永锡尔类。’事亲难，事亲焉可息哉！”“然则赐愿息于妻子。”孔子曰：“诗云：‘刑于寡妻，至于兄弟，以御于家邦。’妻子难，妻子焉可息哉！”“然则赐愿息于朋友。”孔子曰：“诗云：‘朋友攸摄，摄以威仪。’朋友难，朋友焉可息哉！”“然则赐愿息耕。”孔子曰：“诗云：‘昼尔于茅，宵尔索绹，亟其乘屋，其始播百谷。’耕难，耕焉可息哉！”“然则赐无息者乎？”孔子曰：“望其圹，皋如也，颠如也，鬲如也，此则知所息矣。”子贡曰：“大哉！死乎！君子息焉，小人休焉。”"]]},{id:"p086",sentences:[["国风之好色也，传曰：“盈其欲而不愆其止。其诚可比于金石，其声可内于宗庙。”小雅不以于污上，自引而居下，疾今之政以思往者，其言有文焉，其声有哀焉。"]]},{id:"p087",sentences:[["国将兴，必贵师而重傅，贵师而重傅，则法度存。国将衰，必贱师而轻傅；贱师而轻傅，则人有快；人有快则法度坏。"]]},{id:"p088",sentences:[["古者匹夫五十而士。天子诸侯子十九而冠，冠而听治，其教至也。"]]},{id:"p089",sentences:[["君子也者而好之，其人也；其人而不教，不祥。非君子而好之，非其人也；非其人而教之，赍盗粮，借贼兵也。"]]},{id:"p090",sentences:[["不自嗛其行者，言滥过。古之贤人，贱为布衣，贫为匹夫，食则𫗴粥不足，衣则竖褐不完；然而非礼不进，非义不受，安取此？"]]},{id:"p091",sentences:[["子夏家贫，衣若县鹑。人曰：“子何不仕？”曰：“诸侯之骄我者，吾不为臣；大夫之骄我者，吾不复见。柳下惠与后门者同衣，而不见疑，非一日之闻也。争利如蚤甲，而丧其掌。”"]]},{id:"p092",sentences:[["君人者不可以不慎取臣，匹夫不可不慎取友。友者、所以相有也。道不同，何以相有也？均薪施火，火就燥；平地注水，水流湿。夫类之相从也，如此其著也，以友观人，焉所疑？取友善人，不可不慎，是德之基也。诗曰：“无将大车，维尘冥冥。”言无与小人处也。"]]},{id:"p093",sentences:[["蓝苴路作，似知而非。懦弱易夺，似仁而非。悍戆好斗，似勇而非。"]]},{id:"p094",sentences:[["仁义礼善之于人也，辟之若货财粟米之于家也，多有之者富，少有之者贫，至无有者穷。故大者不能，小者不为，是弃国捐身之道也。"]]},{id:"p095",sentences:[["凡物有乘而来，乘其出者，是其反也。"]]},{id:"p096",sentences:[["流言灭之，货色远之。祸之所由生也，生自纤纤也。是故君子蚤绝之。"]]},{id:"p097",sentences:[["言之信者，在乎区盖之间。疑则不言，未问则不言。"]]},{id:"p098",sentences:[["知者明于事，达于数，不可以不诚事也。故曰：“君子难说，说之不以道，不说也。”"]]},{id:"p099",sentences:[["语曰：“流丸止于瓯臾，流言止于知者。”此家言邪说之所以恶儒者也。是非疑，则度之以远事，验之以近物，参之以平心，流言止焉，恶言死焉。"]]},{id:"p100",sentences:[["曾子食鱼，有馀，曰：“泔之。”门人曰：“泔之伤人，不若奥之。”曾子泣涕曰：“有异心乎哉！”伤其闻之晚也。"]]},{id:"p101",sentences:[["无用吾之所短，遇人之所长。故塞而避所短，移而从所仕。疏知而不法，辨察而操僻，勇果而无礼，君子之所憎恶也。"]]},{id:"p102",sentences:[["多言而类，圣人也；少言而法，君子也；多言无法，而流湎然，虽辩，小人也。"]]},{id:"p103",sentences:[["国法禁拾遗，恶民之串以无分得也，有夫分义，则容天下而治；无分义，则一妻一妾而乱。"]]},{id:"p104",sentences:[["天下之人，唯各特意哉，然而有所共予也。言味者予易牙，言音者予师旷，言治者予三王。三王既以定法度，制礼乐而传之，有不用而改自作，何以异于变易牙之和，更师旷之律？无三王之法，天下不待亡，国不待死。"]]},{id:"p105",sentences:[["饮而不食者，蝉也；不饮不食者，浮蝣也。"]]},{id:"p106",sentences:[["虞舜、孝己孝而亲不爱，比干、子胥忠而君不用，仲尼、颜渊知而穷于世。劫迫于暴国而无所辟之，则崇其善，扬其美，言其所长，而不称其所短也。"]]},{id:"p107",sentences:[["惟惟而亡者，诽也；博而穷者，訾也；清之而俞浊者，口也。"]]},{id:"p108",sentences:[["君子能为可贵，不能使人必贵己；能为可用，不能使人必用己。"]]},{id:"p109",sentences:[["诰誓不及五帝，盟诅不及三王，交质子不及五伯。"]]}];return(u,e)=>{const t=p("DaoTextReading");return c(),a("div",null,[e[0]||(e[0]=n("h1",{id:"荀子·第27篇·大略",tabindex:"-1"},[s("荀子·第27篇·大略 "),n("a",{class:"header-anchor",href:"#荀子·第27篇·大略","aria-label":'Permalink to "荀子·第27篇·大略"'},"​")],-1)),e[1]||(e[1]=n("p",null,"本篇讨论：汇集礼义、为学与处世的短章杂论。",-1)),e[2]||(e[2]=n("blockquote",null,[n("p",null,"原文已录入；段级白话、字词点查与三问解读待逐篇补充。原文录入不等于解读完成。")],-1)),e[3]||(e[3]=n("h2",{id:"【原典层】原文",tabindex:"-1"},[s("【原典层】原文 "),n("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),e[4]||(e[4]=n("p",null,"经典阅读保留段落；切换「竹简」可连续通读。此阶段按来源自然段呈现，不为未整理的段落预填释义。",-1)),r(t,{sections:i,"default-mode":"classic",tone:"ink",colophon:"荀子 · 大略","aria-label":"荀子·大略原文"}),e[5]||(e[5]=l("",8))])}}});export{f as __pageData,x as default};
